def get_user_answer(question):
    """Get user input for a question and validate it."""
    while True:
        user_answer = input(question + " (yes/no or type 'quit' to exit): ").lower()
        if user_answer in ['yes', 'no']:
            return user_answer == 'yes'
        elif user_answer == 'quit':
            return False
        else:
            print("Invalid input. Please enter 'yes' or 'no' or 'quit'.")

def play_quiz(questions):
    """Play a quiz with the given questions and keep track of the score."""
    score = 0
    for question in questions:
        if get_user_answer(question):
            score += 1
    return score

